{
  "titre": "Les Trente Glorieuses : réviser la croissance et les transformations",
  "objectifGeneral": "Mobiliser les connaissances sur les Trente Glorieuses en sélectionnant les informations pertinentes et en les organisant",
  "notionsPivots": [
    "la période des Trente Glorieuses",
    "la croissance économique",
    "les transformations sociales",
    "la société de consommation",
    "l'État-providence",
    "les limites de la croissance"
  ],
  "etapes": [
    {
      "titre": "Identifier les grandes étapes chronologiques",
      "objectif": "Mettre en ordre les événements marquants des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Remettre dans l'ordre la chronologie des Trente Glorieuses",
          "objectif": "Ordonner des événements historiques clés par dates",
          "module": "SortParagraphs",
          "palier": "decouverte",
          "duree": 12,
          "consigne": "Relisez les dates et les événements proposés puis placez-les dans l'ordre chronologique croissant en utilisant les numéros."
        }
      ]
    },
    {
      "titre": "Tester ses connaissances sur le vocabulaire et les concepts",
      "objectif": "Reconnaître et définir les notions essentielles des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Quiz sur les Trente Glorieuses : vocabulaire et concepts",
          "objectif": "Associer des définitions à des termes clés",
          "module": "QuizSetVF",
          "palier": "entrainement",
          "duree": 10,
          "consigne": "Répondez par vrai ou faux aux affirmations proposées en vous rappelant les notions vues en classe. La correction s’affichera automatiquement après validation."
        }
      ]
    },
    {
      "titre": "Analyser une source historique",
      "objectif": "Interpréter un document pour en extraire des informations pertinentes",
      "cartes": [
        {
          "titre": "Étudier un graphique de croissance économique",
          "objectif": "Lire un graphique et en décrire l'évolution",
          "module": "Chart",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Observez le graphique fourni présentant l'évolution du PIB en France entre 1945 et 1975. Identifiez les périodes de forte croissance et décrivez-les en quelques phrases."
        }
      ]
    },
    {
      "titre": "Synthétiser les acquis",
      "objectif": "Construire un résumé structuré des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Rédiger un résumé des Trente Glorieuses",
          "objectif": "Sélectionner les informations essentielles et les organiser en une synthèse",
          "module": "Summary",
          "palier": "transfert",
          "duree": 20,
          "consigne": "Choisissez, parmi plusieurs propositions, les affirmations qui résument correctement les aspects économiques, sociaux et les limites des Trente Glorieuses. Justifiez votre sélection en une phrase."
        }
      ]
    }
  ]
}
